      --mech-ok: var(--color-success-text);
      --mech-text: var(--color-text-default);
      --mech-muted: var(--color-text-muted);
      --mech-focus: var(--color-border-focus);
      --mech-pill-bg: var(--color-surface-raised);

      --font-km: 'Noto Sans Khmer', 'Kantumruy Pro', 'Khmer OS Siemreap', 'Leelawadee UI', system-ui, -apple-system, sans-serif;
