        --color-surface-raised: #162033;
        --color-surface-subtle: #111827;
        --color-text-default: #f8fafc;
        --color-text-muted: #cbd5e1;
        --color-border-default: #64748b;
        --color-border-strong: #94a3b8;
        --color-border-focus: #60a5fa;
        --color-action-primary-bg: #38bdf8;
        --color-action-primary-text: #082f49;
        --color-success-text: #34d399;
        --color-success-surface: #064e3b;
        --mech-grid-dot: #334155;
      }
    }

    /* =========================================================================
       2. Responsive Layout & Khmer Typography Discipline
       ========================================================================= */
    *,
    *::before,
    *::after {
      box-sizing: border-box;
    }

    html,
    body {
      margin: 0;
      padding: 0;
      min-height: 100%;
      background-color: var(--mech-page-bg);
      color: var(--mech-text);
      font-family: var(--font-km);
      line-height: 1.7;
