    .label-en {
      font-family: var(--font-latin);
      letter-spacing: 0.01em;
    }

    .mech-shell {
      max-width: 980px;
      margin: 0 auto;
      padding: 20px 16px 32px;
    }

    .mech-figure {
      margin: 0;
      background-color: var(--mech-node-top);
      border: 1.5px solid var(--mech-node-border);
      border-radius: 16px;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 14px;
    }

    .mech-toolbar {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
    }

    .mech-controls,
    .mech-stage-bar {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 8px;
    }

    .mech-btn {
      appearance: none;
      min-height: 44px;
      min-width: 44px;
      padding: 8px 14px;
      border-radius: 10px;
      border: 1.5px solid var(--mech-node-border);
      background-color: var(--mech-node-top);
      color: var(--mech-text);
      font-family: var(--font-km);
      font-size: 14px;
      font-weight: 600;
      line-height: 1.5;
      letter-spacing: 0;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
    }

    .mech-btn:hover {
      border-color: var(--mech-accent);
    }

    .mech-btn:focus-visible {
      outline: 3px solid var(--mech-focus);
      outline-offset: 2px;
    }

    .mech-btn-primary {
      background-color: var(--mech-accent);
      border-color: var(--mech-accent);
      color: var(--mech-accent-text);
    }

    .mech-btn[aria-pressed="true"]:not(.mech-btn-primary) {
      background-color: var(--mech-accent);
      border-color: var(--mech-accent);
      color: var(--mech-accent-text);
    }

    .mech-stage-viewport {
      width: 100%;
      max-width: 100%;
    }

    .mech-svg {
      display: block;
      width: 100%;
      height: auto;
      max-width: 100%;
      overflow: visible;
    }

    .mech-caption {
      margin: 0;
      padding: 12px 14px;
      border-radius: 10px;
      background-color: var(--mech-canvas);
      border: 1px solid var(--mech-node-border);
      font-size: 14px;
      line-height: 1.75;
      color: var(--mech-text);
    }

    .mech-caption-meta {
      margin: 4px 0 0;
      font-size: 13px;
      line-height: 1.6;
      color: var(--mech-muted);
    }

    /* =========================================================================
       3. SVG Typography, Interactive Stage Focus & GPU-Friendly Motion
       ========================================================================= */
    .svg-title-km {
      font-size: 15px;
      font-weight: 700;
      fill: var(--mech-text);
      letter-spacing: 0;
    }

    .svg-node-km {
      font-size: 16px;
      font-weight: 700;
      fill: var(--mech-text);
      letter-spacing: 0;
    }

    .svg-node-en {
      font-size: 13px;
      font-weight: 500;
      fill: var(--mech-muted);
    }

    .svg-badge-num {
      font-size: 13px;
      font-weight: 700;
      fill: var(--mech-accent-text);
    }

    .svg-pill-text {
      font-size: 12px;
      font-weight: 700;
      fill: var(--mech-text);
    }

    .svg-legend-text {
      font-size: 12.5px;
      font-weight: 500;
      fill: var(--mech-muted);
      letter-spacing: 0;
    }

    .mech-node {
      cursor: pointer;
      transition: opacity 180ms ease;
    }

    .mech-node:focus {
      outline: none;
    }

    .mech-node .node-focus-ring {
      opacity: 0;
      transition: opacity 150ms ease;
    }

    .mech-node:focus-visible .node-focus-ring,
    .mech-node:hover .node-focus-ring {
