    .mech-figure[data-active-stage="1"] [data-stage="2"],
    .mech-figure[data-active-stage="1"] [data-stage="3"],
    .mech-figure[data-active-stage="2"] [data-stage="1"],
    .mech-figure[data-active-stage="2"] [data-stage="3"],
    .mech-figure[data-active-stage="3"] [data-stage="1"],
    .mech-figure[data-active-stage="3"] [data-stage="2"] {
      opacity: 0.58;
    }

    .mech-figure[data-active-stage="1"] .mech-node[data-stage="1"] .node-focus-ring,
    .mech-figure[data-active-stage="2"] .mech-node[data-stage="2"] .node-focus-ring,
    .mech-figure[data-active-stage="3"] .mech-node[data-stage="3"] .node-focus-ring {
      opacity: 1;
    }

    /* Signal motion: GPU-friendly stroke-dashoffset, transform & opacity only */
    @keyframes mech-flow {
      from {
        stroke-dashoffset: 60;
      }
      to {
        stroke-dashoffset: 0;
      }
    }

    @keyframes mech-stage-pulse {
      0%,
      100% {
        opacity: 0.18;
        transform: scale(0.97);
      }
      22% {
        opacity: 0.92;
        transform: scale(1.03);
      }
      50% {
        opacity: 0.18;
        transform: scale(0.97);
      }
    }

    .signal-stream {
      stroke-dasharray: 12 18;
      stroke-linecap: round;
      animation: mech-flow 2.4s linear infinite;
    }

    .signal-stream-2 {
      animation-delay: -0.9s;
    }

    .stage-pulse {
      transform-box: fill-box;
      transform-origin: center;
      animation: mech-stage-pulse 3s ease-in-out infinite;
    }

    .stage-pulse-1 {
      animation-delay: 0s;
    }

    .stage-pulse-2 {
      animation-delay: 1s;
    }

    .stage-pulse-3 {
      animation-delay: 2s;
    }

    /* Play/Pause state contract */
    .mech-figure[data-paused="true"] .signal-stream,
    .mech-figure[data-paused="true"] .stage-pulse {
      animation-play-state: paused;
    }

    /* Reduced-motion static clarity fallback */
    @media (prefers-reduced-motion: reduce) {
      .signal-stream,
      .stage-pulse {
        animation: none !important;
        animation-play-state: paused !important;
      }

      .signal-stream {
        opacity: 0.92 !important;
      }

      .stage-pulse {
        opacity: 0.35 !important;
        transform: none !important;
      }
    }
  </style>
</head>
